import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

@Service
public class UserServiceLegacy {
  private final RestTemplate restTemplate;

  public UserServiceLegacy(RestTemplate restTemplate) {
    this.restTemplate = restTemplate;
  }

  public User getUser(Long id) {
    // ❌ OLD: hard-coded URL, manual HTTP, no retry/breaker/timeout.
    // If the users service is down, this call blocks (until the HTTP
    // timeout) and the caller's thread hangs — a downstream outage
    // cascades into this service, exhausting threads.
    ResponseEntity<User> r = restTemplate.getForEntity(
        "http://users-service/users/" + id, User.class); // ❌ OLD
    return r.getBody();
  }
}

