import org.springframework.cloud.openfeign.FeignClient;
import org.springframework.web.bind.annotation.*;

// ✅ NEW: Declarative HTTP client — the interface IS the client.
@FeignClient(name = "users", fallback = UserClientFallback.class)
public interface UserClient {
  @GetMapping("/users/{id}")
  User get(@PathVariable Long id); // ✅ NEW: proxy makes the HTTP call
}

// ✅ NEW: fallback used when the circuit is open or the call fails
@Component
public class UserClientFallback implements UserClient {
  @Override
  public User get(Long id) {
    return User.unknown(); // ✅ NEW: safe default, no cascading failure
  }
}

